typedef unsigned long size_t;
typedef struct _IO_FILE FILE; extern FILE *stdout; int setbuf(FILE*,char*);
void *malloc(size_t); void free(void*);
int printf(const char*,...);
int main(void){
  setbuf(stdout,0);
  char *a=malloc(0x418), *b=malloc(0x418), *guard=malloc(0x20);
  printf("a=%p b=%p guard=%p\n",(void*)a,(void*)b,(void*)guard);
  printf("a.size=0x%lx  (>= 0x400 -> large bin)\n",((unsigned long*)a)[-1]);
  free(a);
  printf("free(a): a -> unsorted bin\n");
  char *big=malloc(0x500);
  printf("malloc(0x500) -> %p : triggers sort, a moves to large bin\n",(void*)big);
  unsigned long *c=(unsigned long*)a;
  printf("fd=%p bk=%p\n",(void*)c[0],(void*)c[1]);
  printf("fd_nextsize=%p bk_nextsize=%p\n",(void*)c[2],(void*)c[3]);
  printf("bk_nextsize offset from chunk start = 0x28\n");
  return 0;
}
